function UIBattleEndFailureJump:InitComponent()
    
    local countsBtn = 3
    local descBtnJump2CultivateInfo = localize("角色提升")
    local descBtnJump2CultivateEquip = localize("强化装备")
    local descBtnJump2FightTeam = localize("调整队伍")
    local listDesc = {}
    table.insert(listDesc, descBtnJump2CultivateInfo)
    table.insert(listDesc, descBtnJump2CultivateEquip)
    table.insert(listDesc, descBtnJump2FightTeam)
    
    local listBindFunction = {}
    table.insert(listBindFunction, Bind(self, self.OpenCultivateInfoDialog))
    table.insert(listBindFunction, Bind(self, self.OpenCultivateEquipDialog))
    table.insert(listBindFunction, Bind(self, self.OpenTeamDialog))
    
    self.showCardDJ = BattleEndMgr:GetJump2CultivateCardDJ()
    if isNull(self.showCardDJ) then return end
    
    for i = 1, countsBtn do
       self:InitJumpBtn(self.ButtonJumpGroup, self.ButtonList, listDesc[i], listBindFunction[i], i)
    end
end

function UIBattleEndFailureJump:GetEntityLockStatus(entityId)
    local lock = not GameUtils.IsUnlockedBySystemTogId(entityId)
    if lock then
        GameUtils.Toast(GameUtils.GetUnlockDescrBySystemTogId(entityId))
    end
    return lock
end

--- 打开养成信息界面
function UIBattleEndFailureJump:OpenCultivateInfoDialog()
    if self.jumpMode == JumpMode.OnlyLoadUIDialog then
        -- UIBattlingCtrlMgr:GetInstance().notResetUICamera = true
        local idLockCultivateInfo = 101
        if self:GetEntityLockStatus(idLockCultivateInfo) then return end
        UIModule.AddUIPage({ id = Constants.UITypeIds.CultivateEntry, parameters = nil })
        GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome }, nil, Constants.LoadingType.MainHome)
    elseif self.jumpMode == JumpMode.LoadSceneAndUIDialog then
        local parameters = { 
            isBackToHomeScene = true,
            isSaveSceneRecord = true, 
            isReleaseBattle   = true,
            extraUIPages      = {
                UIArgs(Constants.UITypeIds.CultivateEntry),
            } 
        }
        GameUtils.OpenLoadingPanel(UIArgs(Constants.UITypeIds.UISceneHome, parameters), nil, Constants.LoadingType.Others, false, true)
    elseif self.jumpMode == JumpMode.Fairyland then
        local parameters = { 
            isBackToHomeScene = true,
            isSaveSceneRecord = true, 
            isReleaseBattle   = true,
            extraUIPages      = {
                UIArgs(Constants.UITypeIds.UIActionPrimaryMapDialog),
                UIArgs(Constants.UITypeIds.UIActionFairylandStageSelectDialog),
                UIArgs(Constants.UITypeIds.CultivateEntry),
            } 
        }
        GameUtils.OpenLoadingPanel(UIArgs(Constants.UITypeIds.UISceneHome, parameters), nil, Constants.LoadingType.Others, false, true)
    else
        -- print("UIBattleEndFailureJump:OpenCultivateEquipDialog: unknown jump mode")
    end
    
end

--- 打开养成装备界面
function UIBattleEndFailureJump:OpenCultivateEquipDialog()
    local idLockCultivateEquip = 106
    if self:GetEntityLockStatus(idLockCultivateEquip) then return end
    if self.jumpMode == JumpMode.OnlyLoadUIDialog then
        -- UIBattlingCtrlMgr:GetInstance().notResetUICamera = true
        local extraParams = {
            cardId = checkInt(self.showCardDJ.cardId),
            playerCardId = checkInt(self.showCardDJ.id)
        }
        local parameters = CardProgressionUtils.CheckJumpCultivateMain(CardProgressionConstants.MainViewType.Equip, extraParams)
        UIModule.AddUIPage({ id = Constants.UITypeIds.CultivateMain,  parameters = parameters })
        GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome }, nil, Constants.LoadingType.MainHome)
    elseif self.jumpMode == JumpMode.LoadSceneAndUIDialog then
        local extraParams = {
            cardId = checkInt(self.showCardDJ.cardId),
            playerCardId = checkInt(self.showCardDJ.id)
        }
        local equipViewParams = CardProgressionUtils.CheckJumpCultivateMain(CardProgressionConstants.MainViewType.Equip, extraParams)
        local parameters = { 
            isBackToHomeScene = true,
            isSaveSceneRecord = true, 
            isReleaseBattle   = true,
            extraUIPages      = {
                UIArgs(Constants.UITypeIds.CultivateMain, equipViewParams),
            } 
        }
        GameUtils.OpenLoadingPanel(UIArgs(Constants.UITypeIds.UISceneHome, parameters), nil, Constants.LoadingType.Others, false, true)
    elseif self.jumpMode == JumpMode.Fairyland then
        local extraParams = {
            cardId = checkInt(self.showCardDJ.cardId),
            playerCardId = checkInt(self.showCardDJ.id)
        }
        local equipViewParams = CardProgressionUtils.CheckJumpCultivateMain(CardProgressionConstants.MainViewType.Equip, extraParams)
        local parameters = { 
            isBackToHomeScene = true,
            isSaveSceneRecord = true, 
            isReleaseBattle   = true,
            extraUIPages      = {
                UIArgs(Constants.UITypeIds.UIActionPrimaryMapDialog),
                UIArgs(Constants.UITypeIds.UIActionFairylandStageSelectDialog),
                UIArgs(Constants.UITypeIds.CultivateMain, equipViewParams),
            } 
        }
        GameUtils.OpenLoadingPanel(UIArgs(Constants.UITypeIds.UISceneHome, parameters), nil, Constants.LoadingType.Others, false, true)
    else
        -- print("UIBattleEndFailureJump:OpenCultivateEquipDialog: unknown jump mode")
    end
end

function UIBattleEndFailureJump:OpenTeamDialog()
    local questId = BattleEndMgr.questId
    local questType = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests)
    local AnnihilationUtils = import('Game.UI.FightReady.UIMainChapter.AnnihilationUtils')
    local isAnni = AnnihilationUtils.QuestTypeIsAnnihilation(questType)
    if isAnni or questType == Constants.IDType.Fairyland then
        -- 歼灭战跳转
        GameUtils.Toast(localize("本关卡需要退出后重新组队"))
    else
        -- 普通关卡跳转
        local fightPreWarMgr = FightPreWarMgr:GetInstance() --- 战前管理类
        local fightTeamArgs = fightPreWarMgr:GetFightTeamArgs()
        fightTeamArgs.levelId = BattleEndMgr.questId    --- 更新关卡Id
        UIModule.AddUIPage({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = fightTeamArgs })
        GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome }, nil, Constants.LoadingType.MainHome)
    end
end

function UIBattleEndFailureJump:InitJumpBtn(goBtn, rootFather, desc, cb, index)
    local go = KTool.Instantiate(rootFather.gameObject, goBtn.gameObject)
    if not IsNull(go) then
        go.name = string.format("%s%s", PrefabName, checkString(index))
        local txtDesc = go.transform:Find("Text")
        if not IsNull(txtDesc) then
            local compTxt = KTool.GetOrAddComponent(txtDesc.gameObject, typeof(Text))
            if not IsNull(compTxt) then
                compTxt.text = desc
            end
        end
        local compBtn = KTool.GetOrAddComponent(go, typeof(Button))
        if not IsNull(compBtn) then
            SetButtonAction(compBtn, cb)
        end
        KTool.SetActive(go, true)
    end
end

